if (uPjNear.x > 0.5) {
  // ?projnear05=1: the same magnification, but from SMOOTH slopes of the LUT (±0.3 u) instead of the derivative
  // of the piecewise-linear lookup (which jumps at every LUT bin and made the E -> tile hand-over flicker row by
  // row into horizontal stripes once the tile no longer shows the same picture as E)
  vec4 La = pjLut(s - 0.3), Lb = pjLut(s + 0.3);
  float w2 = 2.0 * max(Lm.z, 1e-3);
  float dVs = (Lb.x - La.x) / 0.6 * uPjESize.y;
  float dxu = uPjESize.x / w2;
  float dxs = -uPjESize.x * ((Lb.y - La.y) / 0.6 / w2 + (u - Lm.y) * ((Lb.z - La.z) / 0.6) / (w2 * max(Lm.z, 1e-3)));
  vec2 gu = vec2(dFdx(u), dFdy(u)), gs = vec2(dFdx(s), dFdy(s));
  vec2 ka = vec2(dxu * gu.x + dxs * gs.x, dVs * gs.x);
  vec2 kb = vec2(dxu * gu.y + dxs * gs.y, dVs * gs.y);
  mE = abs(ka.x * kb.y - ka.y * kb.x) / max(max(length(ka), length(kb)), 1e-5);
}

